INSERT INTO VENTE
(
    ID,
    DESIGNATION,
    IDMAGASIN,
    DATY,
    ETAT,
    IDCLIENT,
    ESTPREVU,
    DATYPREVU,
    ECHEANCEFACTURE,
    FRAISLIVRAISON,
    MODEPAIEMENT,
    MODELIVRAISON,
    DATELIVRAISON,
    NOMCLIENTDIVERS
)
SELECT
    'VENTEAGR' || LPAD(ROW_NUMBER() OVER(ORDER BY DATE_VENTE,DEPOT,NOMCLIENTDIVERS),6,'0'),

    'Facturation du/de la ',

    (SELECT ID 
       FROM POINT 
      WHERE UPPER(DESCE)=UPPER(DEPOT)),

    DATE_VENTE,

    11,

    'CLI00AGR033',

    0,

    DATE_VENTE,

    0,

    0,

    '0002',

    1,

    DATE_VENTE,

    NOMCLIENTDIVERS

FROM
(
    SELECT DISTINCT
        DATE_VENTE,
        DEPOT,
        NOMCLIENTDIVERS
    FROM TMP_VENTE_FFO
);



INSERT INTO VENTE_DETAILS
(
    ID,
    IDVENTE,
    IDPRODUIT,
    QTE,
    IDDEVISE,
    TAUXDECHANGE,
    DESIGNATION,
    COMPTE,
    UNITE,
    POIDS,
    RISTOURNE,
    PU,
    REMISE,
    TVA,
    PUACHAT,
    PUVENTE,
    PUREVIENT
)

SELECT

    'VENTEDAGR' ||
    LPAD(ROW_NUMBER() OVER(ORDER BY T.DATE_VENTE,T.CODE),6,'0'),

    V.ID,

    I.ID,

    T.QTE,

    'AR',

    1,

    I.LIBELLE,

    I.COMPTE_VENTE,

    I.UNITE,

    0,

    0,

    I.PU,

    0,

    20,

    0,

    0,

    I.PV


FROM TMP_VENTE_FFO T


JOIN VENTE V
ON V.NOMCLIENTDIVERS = T.NOMCLIENTDIVERS
AND V.DATY = T.DATE_VENTE
AND v.ID LIKE 'VENTEAGR%'


JOIN AS_INGREDIENTS I
ON I.CODEBARRE = T.CODE;




UPDATE as_ingredients SET isvente = 1  WHERE id LIKE '%INGAGR%';
UPDATE as_ingredients SET isvente = 0  WHERE id NOT LIKE '%INGAGR%';


DROP TABLE TMP_VENTE_FFO;



UPDATE AS_INGREDIENTS ai
SET ai.TYPEPRODUIT = (
    SELECT CASE m.IDSOUSCATEGORIE
               WHEN 'SOUSCATMOD001' THEN 'TP001'
               WHEN 'SOUSCATMOD002' THEN 'TP002'
               WHEN 'SOUSCATMOD003' THEN 'TP003'
               WHEN 'SOUSCATMOD004' THEN 'TP004'
           END
    FROM MODELE m
    WHERE m.ID = ai.IDMODELE
)
WHERE ai.ID LIKE 'INGAGR%'
AND EXISTS (
    SELECT 1
    FROM MODELE m
    WHERE m.ID = ai.IDMODELE
    AND m.IDSOUSCATEGORIE IN ('SOUSCATMOD001','SOUSCATMOD002','SOUSCATMOD003','SOUSCATMOD004')
);

COMMIT;